// OutRange returns the bars the stream has a value for, as [Core.KST] reports
// them over the same bars; each Update and each Advance adds one to NBElement.
func (sp *KSTStream) OutRange() OutRange {
	return OutRange{BegIdx: sp.outRangeBegIdx, NBElement: sp.outRangeCount}
}

// Advance counts one bar the stream was not fed: OutRange grows by one and
// Value keeps its previous answer. It returns [OutOfRangeEndIndex] once
// OutRange reaches bar [IndexMax].
func (sp *KSTStream) Advance() error {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return OutOfRangeEndIndex
	}
	sp.outRangeCount++
	return nil
}

// Update commits the closed bar inReal and returns its outputs: outKST and
// outKSTSignal. It returns [BadParam] for a bar value that is not finite and
// [OutOfRangeEndIndex] once OutRange reaches bar [IndexMax], both before
// anything changes.
func (sp *KSTStream) Update(inReal float64) (float64, float64, error) {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return 0, 0, OutOfRangeEndIndex
	}
	if !isFinite(inReal) {
		return 0, 0, BadParam
	}
	kstStepImpl(sp, inReal)
	sp.outRangeCount++
	return sp.cur_outKST, sp.cur_outKSTSignal, nil
}

// Peek returns what Update would return for the bar inReal, changing nothing.
