// Value returns the outputs at the last bar of OutRange, in Update's order;
// Peek does not change them.
func (sp *KSTStream) Value() (float64, float64) {
	return sp.cur_outKST, sp.cur_outKSTSignal
}

// Clone returns an independent copy of the stream at the same bar: the two
// evolve separately and share only the [Core].
func (sp *KSTStream) Clone() *KSTStream {
	cl := *sp
	cl.ring_den1_inReal = append(sp.ring_den1_inReal[:0:0], sp.ring_den1_inReal...)
	cl.ring_den2_inReal = append(sp.ring_den2_inReal[:0:0], sp.ring_den2_inReal...)
	cl.ring_den3_inReal = append(sp.ring_den3_inReal[:0:0], sp.ring_den3_inReal...)
	cl.ring_den4_inReal = append(sp.ring_den4_inReal[:0:0], sp.ring_den4_inReal...)
	cl.cb_ring1 = append(sp.cb_ring1[:0:0], sp.cb_ring1...)
	cl.cb_ring2 = append(sp.cb_ring2[:0:0], sp.cb_ring2...)
	cl.cb_ring3 = append(sp.cb_ring3[:0:0], sp.cb_ring3...)
	cl.cb_ring4 = append(sp.cb_ring4[:0:0], sp.cb_ring4...)
	cl.cb_sigRing = append(sp.cb_sigRing[:0:0], sp.cb_sigRing...)
	return &cl
}

